PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
PRAGMA synchronous=FULL;
PRAGMA secure_delete=ON;
CREATE TABLE IF NOT EXISTS metadata(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admins(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES admins(id), csrf TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS config_revisions(revision INTEGER PRIMARY KEY, config_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS config_drafts(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES admins(id), base_revision INTEGER NOT NULL, config_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS personality_versions(revision INTEGER PRIMARY KEY, personality_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS secrets(id TEXT PRIMARY KEY, kind TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, source_key TEXT UNIQUE, title TEXT NOT NULL, context_epoch INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), owner_id TEXT NOT NULL, client_message_id TEXT NOT NULL, input TEXT NOT NULL, config_json TEXT NOT NULL, context_epoch INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','running','completed','failed','cancelled','interrupted')), response TEXT, error TEXT, skill_id TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(conversation_id,client_message_id));
CREATE INDEX IF NOT EXISTS runs_queue ON runs(status,created_at);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), run_id TEXT NOT NULL REFERENCES runs(id), role TEXT NOT NULL CHECK(role IN ('user','assistant')), content TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(run_id,role));
CREATE TABLE IF NOT EXISTS records(id TEXT PRIMARY KEY, kind TEXT NOT NULL, owner_id TEXT NOT NULL, visibility TEXT NOT NULL CHECK(visibility IN ('private','shared')), revision INTEGER NOT NULL, payload TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER);
CREATE INDEX IF NOT EXISTS record_scope ON records(kind,owner_id,visibility,deleted_at,updated_at);
CREATE VIRTUAL TABLE IF NOT EXISTS record_fts USING fts5(content, tokenize='trigram');
CREATE TRIGGER IF NOT EXISTS record_insert AFTER INSERT ON records WHEN new.deleted_at IS NULL BEGIN INSERT INTO record_fts(rowid,content) VALUES(new.rowid,new.payload); END;
CREATE TRIGGER IF NOT EXISTS record_update AFTER UPDATE ON records BEGIN DELETE FROM record_fts WHERE rowid=old.rowid; INSERT INTO record_fts(rowid,content) SELECT new.rowid,new.payload WHERE new.deleted_at IS NULL; END;
CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY AUTOINCREMENT, owner_id TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, title TEXT NOT NULL, resource_id TEXT, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS audit_owner ON audit_events(owner_id,id);
CREATE TABLE IF NOT EXISTS channel_inbox(event_key TEXT PRIMARY KEY, channel TEXT NOT NULL, received_at INTEGER NOT NULL, run_id TEXT);
CREATE TABLE IF NOT EXISTS channel_outbox(id TEXT PRIMARY KEY, run_id TEXT NOT NULL UNIQUE REFERENCES runs(id), channel TEXT NOT NULL, target_json TEXT NOT NULL, credential_ref TEXT NOT NULL, content TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','sending','sent','failed','unknown','cancelled')), error TEXT, platform_message_id TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
